import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { SpecData } from '../types';

interface SpecsChartProps {
  data: SpecData[];
  isDark: boolean;
}

const SpecsChart: React.FC<SpecsChartProps> = ({ data, isDark }) => {
  return (
    <div className="h-[300px] w-full">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart
          data={data}
          margin={{
            top: 20,
            right: 30,
            left: 20,
            bottom: 5,
          }}
        >
          <CartesianGrid strokeDasharray="3 3" stroke={isDark ? '#333' : '#e5e5e5'} />
          <XAxis 
            dataKey="name" 
            stroke={isDark ? '#a8a29e' : '#57534e'} 
            tick={{ fontFamily: 'Inter', fontSize: 12 }}
          />
          <YAxis 
            stroke={isDark ? '#a8a29e' : '#57534e'}
            tick={{ fontFamily: 'Inter', fontSize: 12 }}
          />
          <Tooltip 
            cursor={{ fill: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)' }}
            contentStyle={{ 
              backgroundColor: isDark ? '#1a1a1a' : '#fff', 
              borderColor: isDark ? '#333' : '#e5e5e5',
              fontFamily: 'Inter',
              color: isDark ? '#fff' : '#333'
            }}
          />
          <Legend />
          <Bar dataKey="value" name="AgroVibe Quality" fill="#d4af37" radius={[4, 4, 0, 0]} />
          <Bar dataKey="standard" name="Market Standard" fill={isDark ? '#2f4b3a' : '#143d28'} radius={[4, 4, 0, 0]} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export default SpecsChart;

import React, { useState, useEffect } from 'react';
import { 
  Menu, X, Globe, Moon, Sun, Leaf, Droplets, Scale, 
  MapPin, Truck, CheckCircle, ChevronRight, FileText, ArrowRight 
} from 'lucide-react';
import { TRANSLATIONS, PRODUCTS } from './constants';
import { Language, Theme } from './types';
import SpecsChart from './components/SpecsChart';

function App() {
  const [lang, setLang] = useState<Language>('EN');
  const [theme, setTheme] = useState<Theme>('light');
  const [isNavOpen, setIsNavOpen] = useState(false);
  const [activeProduct, setActiveProduct] = useState(PRODUCTS[0]);
  const [scrolled, setScrolled] = useState(false);

  const t = TRANSLATIONS[lang];

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
    if (theme === 'light') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  };

  const isDark = theme === 'dark';

  return (
    <div className={`min-h-screen transition-colors duration-500 font-sans ${isDark ? 'bg-charcoal text-stone-200' : 'bg-ivory text-stone-800'}`}>

      {/* Navigation */}
      <nav className={`fixed w-full z-50 transition-all duration-300 ${scrolled ? (isDark ? 'bg-forest-900/90 backdrop-blur-md border-b border-white/5' : 'bg-white/90 backdrop-blur-md border-b border-stone-200 shadow-sm') : 'bg-transparent'}`}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-20">
            {/* Logo */}
            <div className="flex items-center gap-2">
              <div className={`p-2 rounded-full ${isDark ? 'bg-gold-500/20 text-gold-400' : 'bg-forest-800 text-white'}`}>
                <Leaf size={24} />
              </div>
              <span className={`font-serif text-2xl font-bold tracking-tight ${isDark ? 'text-stone-100' : 'text-forest-800'}`}>AgroVibe</span>
            </div>

            {/* Desktop Menu */}
            <div className="hidden md:flex items-center space-x-8">
              <a href="#home" className="hover:text-gold-600 transition-colors font-medium">{t.nav.home}</a>
              <a href="#products" className="hover:text-gold-600 transition-colors font-medium">{t.nav.products}</a>
              <a href="#specs" className="hover:text-gold-600 transition-colors font-medium">{t.nav.specs}</a>
              <a href="#traceability" className="hover:text-gold-600 transition-colors font-medium">{t.nav.traceability}</a>

              <div className="h-6 w-px bg-current opacity-20 mx-2"></div>

              {/* Controls */}
              <div className="flex items-center space-x-4">
                <button onClick={toggleTheme} className="p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition-colors">
                  {isDark ? <Sun size={20} /> : <Moon size={20} />}
                </button>

                <div className="relative group">
                  <button className="flex items-center gap-1 font-medium hover:text-gold-600">
                    <Globe size={20} />
                    <span>{lang}</span>
                  </button>
                  <div className="absolute right-0 mt-2 w-32 py-2 bg-white dark:bg-neutral-800 rounded-lg shadow-xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 transform origin-top-right border border-stone-100 dark:border-stone-700">
                    {(['EN', 'ID', 'CN'] as Language[]).map((l) => (
                      <button 
                        key={l}
                        onClick={() => setLang(l)}
                        className={`block w-full text-left px-4 py-2 hover:bg-stone-50 dark:hover:bg-white/5 ${lang === l ? 'text-gold-600 font-bold' : ''}`}
                      >
                        {l === 'CN' ? '中文' : l === 'ID' ? 'Bahasa' : 'English'}
                      </button>
                    ))}
                  </div>
                </div>

                <a href="#contact" className={`px-6 py-2 rounded-full font-medium transition-all transform hover:scale-105 ${isDark ? 'bg-gold-500 text-forest-900 hover:bg-gold-400' : 'bg-forest-800 text-white hover:bg-forest-900'}`}>
                  {t.nav.contact}
                </a>
              </div>
            </div>

            {/* Mobile Toggle */}
            <div className="md:hidden flex items-center">
              <button onClick={() => setIsNavOpen(!isNavOpen)}>
                {isNavOpen ? <X size={28} /> : <Menu size={28} />}
              </button>
            </div>
          </div>
        </div>

        {/* Mobile Menu */}
        {isNavOpen && (
          <div className={`md:hidden absolute w-full ${isDark ? 'bg-neutral-900 border-b border-white/10' : 'bg-white border-b border-stone-200'} shadow-lg`}>
            <div className="px-4 pt-2 pb-6 space-y-4 flex flex-col items-center">
              <a href="#home" onClick={() => setIsNavOpen(false)} className="text-lg py-2">{t.nav.home}</a>
              <a href="#products" onClick={() => setIsNavOpen(false)} className="text-lg py-2">{t.nav.products}</a>
              <a href="#specs" onClick={() => setIsNavOpen(false)} className="text-lg py-2">{t.nav.specs}</a>
              <div className="flex gap-4 pt-4">
                 <button onClick={toggleTheme} className="p-2 rounded-full bg-black/5 dark:bg-white/10">
                  {isDark ? <Sun size={20} /> : <Moon size={20} />}
                </button>
                <div className="flex gap-2 bg-black/5 dark:bg-white/10 rounded-full p-1">
                   {(['EN', 'ID', 'CN'] as Language[]).map((l) => (
                      <button 
                        key={l}
                        onClick={() => setLang(l)}
                        className={`px-3 py-1 rounded-full text-sm ${lang === l ? 'bg-white dark:bg-neutral-700 shadow-sm' : ''}`}
                      >
                        {l}
                      </button>
                    ))}
                </div>
              </div>
            </div>
          </div>
        )}
      </nav>

      {/* Hero Section */}
      <section id="home" className="relative h-screen flex items-center justify-center overflow-hidden">
        {/* Background Overlay */}
        <div className="absolute inset-0 z-0">
          <img 
            src="https://picsum.photos/id/113/2500/1600" // Tea plantation lookalike
            alt="Plantation" 
            className="w-full h-full object-cover"
          />
          <div className={`absolute inset-0 ${isDark ? 'bg-gradient-to-b from-black/70 via-black/50 to-charcoal' : 'bg-gradient-to-b from-black/40 via-black/20 to-ivory'}`}></div>
        </div>

        <div className="relative z-10 max-w-5xl mx-auto px-4 text-center mt-20">
          <div className="inline-block mb-6 px-4 py-1.5 rounded-full bg-white/10 backdrop-blur-md border border-white/20 text-white text-sm tracking-widest uppercase animate-fade-in-up">
            Export Quality Certified
          </div>
          <h1 className="font-serif text-5xl md:text-7xl font-bold text-white mb-6 leading-tight drop-shadow-lg">
            {t.hero.title}
          </h1>
          <p className="text-xl md:text-2xl text-stone-200 mb-10 max-w-3xl mx-auto font-light">
            {t.hero.subtitle}
          </p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <a href="#products" className="px-8 py-4 bg-gold-500 hover:bg-gold-400 text-forest-900 rounded-lg font-bold text-lg transition-transform hover:-translate-y-1 shadow-lg shadow-gold-500/20">
              {t.hero.ctaPrimary}
            </a>
            <a href="#contact" className="px-8 py-4 bg-white/10 hover:bg-white/20 backdrop-blur-md border border-white/30 text-white rounded-lg font-bold text-lg transition-transform hover:-translate-y-1">
              {t.hero.ctaSecondary}
            </a>
          </div>
        </div>
      </section>

      {/* Product Catalog */}
      <section id="products" className="py-24 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto">
        <div className="text-center mb-16">
          <h2 className={`font-serif text-4xl font-bold mb-4 ${isDark ? 'text-gold-400' : 'text-forest-800'}`}>
            {t.products.title}
          </h2>
          <p className="text-lg opacity-80">{t.products.subtitle}</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
          {PRODUCTS.map((product) => (
            <div 
              key={product.id}
              onClick={() => setActiveProduct(product)}
              className={`group cursor-pointer rounded-2xl overflow-hidden transition-all duration-500 ${isDark ? 'bg-neutral-800 hover:shadow-gold-500/10' : 'bg-white hover:shadow-2xl'} shadow-lg border border-transparent hover:border-gold-500/50`}
            >
              <div className="h-64 overflow-hidden relative">
                <img 
                  src={product.image} 
                  alt={product.title} 
                  className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
                />
                <div className="absolute bottom-0 left-0 w-full p-4 bg-gradient-to-t from-black/80 to-transparent">
                  <div className="flex gap-2">
                    {product.tags.slice(0, 2).map(tag => (
                      <span key={tag} className="px-2 py-1 text-xs rounded bg-white/20 backdrop-blur-md text-white border border-white/20">
                        {tag}
                      </span>
                    ))}
                  </div>
                </div>
              </div>
              <div className="p-8">
                <h3 className={`font-serif text-2xl font-bold mb-3 ${isDark ? 'text-stone-100' : 'text-forest-900'}`}>
                  {product.title}
                </h3>
                <p className="opacity-70 mb-6 leading-relaxed line-clamp-3">
                  {product.description}
                </p>
                <div className="flex items-center text-gold-500 font-semibold group-hover:translate-x-2 transition-transform">
                  View Specs <ChevronRight size={18} />
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Live Spec Sheet (Recharts) */}
      <section id="specs" className={`py-24 px-4 ${isDark ? 'bg-neutral-800' : 'bg-stone-100'}`}>
        <div className="max-w-7xl mx-auto">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-center">

            {/* Left: Interactive Chart */}
            <div className={`p-8 rounded-3xl ${isDark ? 'bg-neutral-900 border border-white/5' : 'bg-white shadow-xl'}`}>
              <div className="flex justify-between items-center mb-8">
                <h3 className="font-serif text-2xl font-bold">{activeProduct.title} Analysis</h3>
                <span className="text-xs font-mono opacity-50">LIVE DATA REF: 2024-Q1</span>
              </div>

              <SpecsChart data={activeProduct.specs} isDark={isDark} />

              <div className="mt-8 grid grid-cols-3 gap-4 text-center">
                {activeProduct.specs.map((spec) => (
                  <div key={spec.name} className={`p-4 rounded-xl ${isDark ? 'bg-white/5' : 'bg-stone-50'}`}>
                    <div className="text-2xl font-bold text-gold-500">{spec.value}{spec.unit}</div>
                    <div className="text-xs opacity-60 uppercase tracking-wider mt-1">{spec.name}</div>
                  </div>
                ))}
              </div>
            </div>

            {/* Right: Text Content */}
            <div>
              <div className="inline-block p-3 rounded-2xl bg-gold-500/10 text-gold-600 mb-6">
                <Scale size={32} />
              </div>
              <h2 className={`font-serif text-4xl font-bold mb-6 ${isDark ? 'text-white' : 'text-forest-900'}`}>
                {t.specs.title}
              </h2>
              <p className="text-xl opacity-80 mb-8 leading-relaxed">
                {t.specs.subtitle} We maintain rigorous laboratory testing for every batch. Our cloves contain significantly higher eugenol levels compared to the market average, and our cocoa beans are fermented to perfection.
              </p>

              <ul className="space-y-4 mb-10">
                <li className="flex items-center gap-3">
                  <CheckCircle className="text-green-500" size={20} />
                  <span>FSSC 22000 Certified Processing</span>
                </li>
                <li className="flex items-center gap-3">
                  <CheckCircle className="text-green-500" size={20} />
                  <span>Moisture Content Guaranteed &lt;12%</span>
                </li>
                <li className="flex items-center gap-3">
                  <CheckCircle className="text-green-500" size={20} />
                  <span>Heavy Metal & Pesticide Free</span>
                </li>
              </ul>

              <button className={`flex items-center gap-3 px-8 py-4 rounded-xl font-bold transition-all ${isDark ? 'bg-white text-black hover:bg-stone-200' : 'bg-forest-900 text-white hover:bg-forest-800'}`}>
                <FileText size={20} />
                {t.specs.downloadBtn}
              </button>
            </div>

          </div>
        </div>
      </section>

      {/* Traceability / Sourcing Map */}
      <section id="traceability" className="py-24 px-4 max-w-7xl mx-auto">
        <div className="text-center mb-16">
          <h2 className={`font-serif text-4xl font-bold mb-4 ${isDark ? 'text-gold-400' : 'text-forest-800'}`}>
            {t.traceability.title}
          </h2>
          <p className="text-lg opacity-80">{t.traceability.subtitle}</p>
        </div>

        {/* Visual Map / Timeline Wrapper */}
        <div className="relative">
          {/* Abstract Path Line (Mobile Hidden) */}
          <div className="hidden md:block absolute top-1/2 left-0 w-full h-1 bg-gradient-to-r from-transparent via-gold-500/30 to-transparent -translate-y-1/2 z-0"></div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-8 relative z-10">
            {[
              { icon: <Leaf size={24} />, title: t.traceability.steps.farm, loc: 'Sulawesi & Java' },
              { icon: <Droplets size={24} />, title: t.traceability.steps.process, loc: 'Drying Facility' },
              { icon: <Scale size={24} />, title: t.traceability.steps.qc, loc: 'Surabaya Lab' },
              { icon: <Truck size={24} />, title: t.traceability.steps.export, loc: 'Port of Tanjung Perak' },
            ].map((step, idx) => (
              <div key={idx} className={`p-6 rounded-2xl border ${isDark ? 'bg-charcoal border-white/10' : 'bg-white border-stone-200'} text-center group hover:-translate-y-2 transition-transform duration-300`}>
                <div className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center mb-4 ${isDark ? 'bg-forest-900 text-gold-400' : 'bg-forest-50 text-forest-800 group-hover:bg-forest-800 group-hover:text-white'} transition-colors`}>
                  {step.icon}
                </div>
                <h4 className="font-bold text-lg mb-2">{step.title}</h4>
                <div className="flex items-center justify-center gap-1 text-sm opacity-60">
                  <MapPin size={14} />
                  {step.loc}
