              <ul className="space-y-6 mb-12">
                <li className="flex items-start gap-4">
                  <div className="mt-1 text-green-500"><CheckCircle size={20} /></div>
                  <div>
                    <strong className="block mb-1">FSSC 22000 Certified Processing</strong>
                    <span className="text-sm opacity-60">Ensuring the highest food safety standards for global export.</span>
