                <span>
                  Menara BCA Grand Indonesia<br/>
                  Jl. M.H. Thamrin No.1<br/>
                  Jakarta 10310, Indonesia
                </span>
              </li>
              <li className="flex gap-3">
                 <Phone size={20} className="shrink-0 text-gold-500" />
                 <span>+62 812 3456 7890</span>
              </li>
              <li className="flex gap-3">
                 <Mail size={20} className="shrink-0 text-gold-500" />
                 <span>export@agrovibe.id</span>
              </li>
            </ul>
          </div>

           {/* Column 4: Newsletter */}
           <div>
            <h4 className="font-bold text-lg mb-6">{t.footer.newsletter}</h4>
            <p className="opacity-60 mb-4">{t.footer.newsletterDesc}</p>
            <div className="flex gap-2">
              <input 
                type="email" 
                placeholder="Email Address" 
                className={`w-full px-4 py-3 rounded-lg border ${isDark ? 'bg-white/5 border-white/10' : 'bg-white border-stone-200'} focus:outline-none focus:border-gold-500`}
              />
              <button className="bg-gold-500 text-forest-900 p-3 rounded-lg hover:bg-gold-400 transition-colors">
                <ChevronRight size={20} />
              </button>
            </div>
          </div>
        </div>

        <div className={`pt-8 border-t ${isDark ? 'border-white/5' : 'border-stone-200'} flex flex-col md:flex-row justify-between items-center gap-4 opacity-50`}>
          <div>&copy; 2024 AgroVibe Exports. {t.footer.rights}</div>
          <div className="flex gap-6 text-xs uppercase tracking-wider">
            <a href="#" className="hover:underline">Privacy Policy</a>
            <a href="#" className="hover:underline">Terms of Service</a>
            <a href="#" className="hover:underline">Sitemap</a>
          </div>
        </div>
      </footer>
    </div>
  );
}

