import React, { useState, useEffect } from 'react';
import { Translation } from '../types';
import { Cookie } from 'lucide-react';

interface CookieConsentProps {
  t: Translation['cookieConsent'];
  onAccept: () => void;
  onDecline: () => void;
}

const CookieConsent: React.FC<CookieConsentProps> = ({ t, onAccept, onDecline }) => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    // Small delay to make it pop up nicely after page load
    const timer = setTimeout(() => setIsVisible(true), 1500);
    return () => clearTimeout(timer);
  }, []);

  if (!isVisible) return null;

  return (
    <div className="fixed bottom-4 left-4 right-4 md:left-auto md:right-4 md:w-[28rem] z-[100] animate-fade-up">
      <div className="bg-white/90 dark:bg-zinc-900/90 backdrop-blur-xl border border-zinc-200 dark:border-zinc-800 p-6 rounded-3xl shadow-2xl flex flex-col gap-4">
        <div className="flex items-start gap-4">
          <div className="p-3 bg-brand-100 dark:bg-brand-900/30 text-brand-600 rounded-full shrink-0">
             <Cookie size={24} />
          </div>
          <p className="text-sm text-zinc-600 dark:text-zinc-300 leading-relaxed">
            {t.text}
          </p>
        </div>
        <div className="flex gap-3 justify-end">
           <button 
             onClick={onDecline}
             className="px-4 py-2 text-sm font-bold text-zinc-500 hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-white transition-colors"
           >
             {t.decline}
           </button>
           <button 
             onClick={onAccept}
             className="px-6 py-2 bg-brand-500 hover:bg-brand-600 text-white text-sm font-bold rounded-full transition-all shadow-lg hover:shadow-brand-500/20"
           >
             {t.accept}
           </button>
        </div>
      </div>
    </div>
  );
};

export default CookieConsent;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Menu, X, Globe, Moon, Sun, ArrowRight, ArrowUpRight,
  ChevronRight, ChevronDown, BarChart3, Package, Truck, ShieldCheck, Mail, ArrowDown,
  Facebook, Linkedin, Instagram, Sprout, Leaf, Activity, Zap, MapPin, Phone, User, Check, Clock
} from 'lucide-react';
import { TRANSLATIONS, PRODUCTS, LANG_CONFIG } from './constants';
import { Language, Theme } from './types';
import SpecsChart from './components/SpecsChart';
import AboutPage from './components/AboutPage';
import CookieConsent from './components/CookieConsent';

type ViewState = 'home' | 'about';

function App() {
  // Initialize state from localStorage if available
  const [lang, setLang] = useState<Language>(() => {
    return (localStorage.getItem('agrovibe_lang') as Language) || 'EN';
  });

  const [theme, setTheme] = useState<Theme>(() => {
    return (localStorage.getItem('agrovibe_theme') as Theme) || 'light';
  });

  const [cookieConsent, setCookieConsent] = useState<'accepted' | 'declined' | null>(() => {
    return localStorage.getItem('agrovibe_cookie_consent') as 'accepted' | 'declined' | null;
  });

  const [isNavOpen, setIsNavOpen] = useState(false);
  const [isClientModalOpen, setIsClientModalOpen] = useState(false);
  const [isLangMenuOpen, setIsLangMenuOpen] = useState(false);

  // Store the INDEX of the active product to maintain selection across language changes
  const [activeProductIndex, setActiveProductIndex] = useState(0);

  const [scrolled, setScrolled] = useState(false);
  const [view, setView] = useState<ViewState>('home');
  const [worldTimes, setWorldTimes] = useState({ kendari: '', london: '', china: '' });
  const langMenuRef = useRef<HTMLDivElement>(null);

  const t = TRANSLATIONS[lang];
  const products = PRODUCTS[lang];
  const activeProduct = products[activeProductIndex];

  // Persist Language Choice
  useEffect(() => {
    if (cookieConsent === 'accepted') {
      localStorage.setItem('agrovibe_lang', lang);
    }
  }, [lang, cookieConsent]);

  // Persist Theme Choice
  useEffect(() => {
    if (cookieConsent === 'accepted') {
      localStorage.setItem('agrovibe_theme', theme);
    }

    if (theme === 'light') {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
  }, [theme, cookieConsent]);

  // RTL Logic for Arabic
  useEffect(() => {
    if (lang === 'AE') {
      document.documentElement.dir = 'rtl';
      document.documentElement.lang = 'ar';
    } else {
      document.documentElement.dir = 'ltr';
      document.documentElement.lang = lang.toLowerCase();
    }
  }, [lang]);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // World Time Updater
  useEffect(() => {
    const updateTime = () => {
      const getCityTime = (zone: string) => new Date().toLocaleTimeString('en-US', { 
        timeZone: zone, 
        hour: '2-digit', 
        minute: '2-digit',
        hour12: false 
      });

      setWorldTimes({
        kendari: getCityTime('Asia/Makassar'), // Kendari is in WITA (UTC+8) same as Makassar
        london: getCityTime('Europe/London'),
        china: getCityTime('Asia/Shanghai')
      });
    };
    updateTime();
    const interval = setInterval(updateTime, 1000); // Update every second for blinking effect preference
    return () => clearInterval(interval);
  }, []);

  // Close lang menu when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (langMenuRef.current && !langMenuRef.current.contains(event.target as Node)) {
        // Only close desktop menu here, mobile has its own overlay
        if (window.innerWidth >= 768) {
           setIsLangMenuOpen(false);
        }
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Scroll to top when view changes
  useEffect(() => {
    window.scrollTo(0, 0);
    setIsNavOpen(false); // Ensure nav closes on view change
  }, [view]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const handleCookieAccept = () => {
    setCookieConsent('accepted');
    localStorage.setItem('agrovibe_cookie_consent', 'accepted');
    // Immediately save current preferences upon acceptance
    localStorage.setItem('agrovibe_lang', lang);
    localStorage.setItem('agrovibe_theme', theme);
  };

  const handleCookieDecline = () => {
    setCookieConsent('declined');
    localStorage.setItem('agrovibe_cookie_consent', 'declined');
    // Clear existing preferences if declined
    localStorage.removeItem('agrovibe_lang');
    localStorage.removeItem('agrovibe_theme');
  };

  const isDark = theme === 'dark';

  return (
    <div className={`min-h-screen transition-colors duration-700 font-sans selection:bg-brand-500 selection:text-white ${isDark ? 'bg-zinc-950 text-zinc-100' : 'bg-[#f8f8f7] text-zinc-900'} overflow-x-hidden`}>

      {/* Noise Texture Overlay */}
      <div className="fixed inset-0 pointer-events-none z-0 bg-noise opacity-40 mix-blend-overlay"></div>

      {/* Navigation */}
      <nav className={`fixed top-0 left-0 w-full z-40 transition-all duration-500 ${scrolled ? 'py-3 md:py-4' : 'py-6 md:py-8'}`}>
        <div className="w-[92%] md:max-w-[95%] mx-auto bg-white/80 dark:bg-black/50 backdrop-blur-md border border-white/20 dark:border-white/10 rounded-full px-4 md:px-8 py-3 md:py-4 flex justify-between items-center shadow-sm hover:shadow-md transition-shadow">
          {/* Brand */}
          <button onClick={() => setView('home')} className="flex items-center gap-2 md:gap-3 group">
             <div className="w-8 h-8 md:w-10 md:h-10 bg-brand-500 rounded-full flex items-center justify-center text-white group-hover:scale-110 transition-transform shrink-0">
                <Leaf size={18} fill="currentColor" />
             </div>
             <span className="font-bold text-lg md:text-xl tracking-tight">AgroVibe<span className="text-brand-500">.</span></span>
          </button>

          {/* Desktop Links */}
          <div className="hidden md:flex items-center gap-8 text-sm font-medium">
             <button onClick={() => setView('home')} className={`opacity-60 hover:opacity-100 hover:text-brand-500 transition-all ${view === 'home' ? 'opacity-100 text-brand-500' : ''}`}>{t.nav.home}</button>
             <button onClick={() => setView('about')} className={`opacity-60 hover:opacity-100 hover:text-brand-500 transition-all ${view === 'about' ? 'opacity-100 text-brand-500' : ''}`}>{t.nav.about}</button>
             <a href="#products" onClick={(e) => { setView('home'); }} className="opacity-60 hover:opacity-100 hover:text-brand-500 transition-all">{t.nav.products}</a>
             <a href="#specs" onClick={(e) => { setView('home'); }} className="opacity-60 hover:opacity-100 hover:text-brand-500 transition-all">{t.nav.specs}</a>
          </div>

          {/* Actions */}
          <div className="hidden md:flex items-center gap-3 lg:gap-4">
             <button onClick={toggleTheme} className="w-10 h-10 rounded-full border border-zinc-200 dark:border-zinc-800 flex items-center justify-center hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors">
                {isDark ? <Sun size={18} /> : <Moon size={18} />}
             </button>

             {/* Language Dropdown */}
             <div className="relative" ref={langMenuRef}>
               <button 
