            </div>
         </div>

         {/* Middle Section: Links Grid */}
         <div className="max-w-[95rem] mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-12 lg:gap-8 mb-32">

             {/* Column 1: Navigation */}
             <div>
                <span className="block text-xs font-mono text-zinc-500 mb-8 uppercase tracking-widest">{t.footer.exploreLabel}</span>
                <ul className="space-y-4 text-xl md:text-2xl font-medium">
                   <li><button onClick={() => setView('home')} className="hover:text-brand-500 transition-colors hover:translate-x-2 inline-block duration-300 rtl:hover:-translate-x-2">{t.nav.home}</button></li>
                   <li><button onClick={() => setView('about')} className="hover:text-brand-500 transition-colors hover:translate-x-2 inline-block duration-300 rtl:hover:-translate-x-2">{t.nav.about}</button></li>
                   <li><a href="#products" onClick={() => setView('home')} className="hover:text-brand-500 transition-colors hover:translate-x-2 inline-block duration-300 rtl:hover:-translate-x-2">{t.nav.products}</a></li>
                   <li><a href="#specs" onClick={() => setView('home')} className="hover:text-brand-500 transition-colors hover:translate-x-2 inline-block duration-300 rtl:hover:-translate-x-2">{t.nav.specs}</a></li>
                </ul>
             </div>

             {/* Column 2: Socials (Added Gmail and TikTok) */}
             <div>
                <span className="block text-xs font-mono text-zinc-500 mb-8 uppercase tracking-widest">{t.footer.connectLabel}</span>
                <ul className="space-y-4 text-xl md:text-2xl font-medium">
                   <li><a href="mailto:hello@agrovibe.tech" className="hover:text-brand-500 transition-colors flex items-center gap-2 group/link">Gmail <ArrowUpRight size={18} className="opacity-0 group-hover/link:opacity-100 transition-opacity rtl:rotate-270" /></a></li>
                   <li><a href="#" className="hover:text-brand-500 transition-colors flex items-center gap-2 group/link">TikTok <ArrowUpRight size={18} className="opacity-0 group-hover/link:opacity-100 transition-opacity rtl:rotate-270" /></a></li>
                   <li><a href="#" className="hover:text-brand-500 transition-colors flex items-center gap-2 group/link">LinkedIn <ArrowUpRight size={18} className="opacity-0 group-hover/link:opacity-100 transition-opacity rtl:rotate-270" /></a></li>
                   <li><a href="#" className="hover:text-brand-500 transition-colors flex items-center gap-2 group/link">Instagram <ArrowUpRight size={18} className="opacity-0 group-hover/link:opacity-100 transition-opacity rtl:rotate-270" /></a></li>
