      const getCityTime = (zone: string) => new Date().toLocaleTimeString('en-US', { timeZone: zone, hour: '2-digit', minute: '2-digit', hour12: false });
      setWorldTimes({ kendari: getCityTime('Asia/Makassar'), london: getCityTime('Europe/London'), china: getCityTime('Asia/Shanghai') });
