                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 md:gap-8">
                   {products.map((product, idx) => (
                      <div key={product.id} onClick={() => setActiveProductIndex(idx)} className={`group relative h-[450px] md:h-[550px] lg:h-[600px] rounded-[3rem] overflow-hidden cursor-pointer transition-all duration-700 ${activeProductIndex === idx ? 'ring-2 ring-brand-500 ring-offset-4 dark:ring-offset-zinc-950 scale-[1.02]' : 'hover:scale-[1.01]'}`}>
                         <img src={product.image} className="absolute inset-0 w-full h-full object-cover transition-transform duration-[1.5s] group-hover:scale-110" alt={product.title} />
                         <div className="absolute inset-0 bg-gradient-to-t from-black/95 via-black/30 to-transparent transition-opacity duration-700 opacity-80 group-hover:opacity-100" />
                         <div className="absolute top-8 right-8 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full px-4 py-2 text-white text-[10px] font-black uppercase tracking-widest">{product.tags[0]}</div>
                         <div className="absolute bottom-0 left-0 w-full p-8 md:p-10 transform translate-y-6 group-hover:translate-y-0 transition-transform duration-700">
                            <h3 className="text-2xl md:text-3xl text-white font-black leading-none mb-4 italic uppercase tracking-tighter">{product.title}</h3>
                            <p className="text-sm text-white/60 font-light line-clamp-3 mb-6 opacity-0 group-hover:opacity-100 transition-opacity duration-700 delay-100 leading-relaxed">{product.description}</p>
                            <div className="w-14 h-14 bg-brand-500 rounded-full flex items-center justify-center text-white opacity-0 group-hover:opacity-100 transition-all duration-500 hover:rotate-12 hover:scale-110 shadow-2xl"><ArrowUpRight size={28} /></div>
                         </div>
                      </div>
                   ))}
                </div>
             </div>
          </section>

          <section id="specs" className="py-32 md:py-56 px-4 md:px-12 bg-zinc-50 dark:bg-black relative overflow-hidden">
             <div className="max-w-[95rem] mx-auto relative z-10">
                <div className="flex flex-col lg:flex-row gap-20 lg:gap-40">
                   <div className="lg:w-[40%] lg:sticky lg:top-40 h-fit">
                      <span className="text-brand-500 font-mono text-xs uppercase tracking-[0.5em] mb-8 block italic">/// {t.specs.liveDataLabel}</span>
                      <h2 className="text-6xl md:text-8xl font-black uppercase tracking-tighter leading-[0.8] mb-12 italic">{t.specs.title}</h2>
                      <p className="text-xl md:text-3xl font-light opacity-70 leading-snug mb-16">{t.specs.subtitle}</p>
                      <div className="space-y-10">
                         <div className="flex items-center gap-8 group">
                            <div className="w-20 h-20 bg-brand-500/10 text-brand-500 rounded-[2rem] flex items-center justify-center shrink-0 border border-brand-500/20 group-hover:rotate-12 transition-transform duration-500"><Activity size={32} /></div>
                            <div><div className="text-2xl font-bold mb-1">{t.specs.realTimeTitle}</div><div className="text-sm opacity-50 uppercase tracking-widest font-mono">{t.specs.realTimeDesc}</div></div>
                         </div>
                         <div className="flex items-center gap-8 group">
                            <div className="w-20 h-20 bg-brand-500/10 text-brand-500 rounded-[2rem] flex items-center justify-center shrink-0 border border-brand-500/20 group-hover:-rotate-12 transition-transform duration-500"><ShieldCheck size={32} /></div>
                            <div><div className="text-2xl font-bold mb-1">{t.specs.certTitle}</div><div className="text-sm opacity-50 uppercase tracking-widest font-mono">{t.specs.certDesc}</div></div>
                         </div>
                      </div>
                   </div>
                   <div className="lg:w-[60%] space-y-12">
                      <div className="bg-white dark:bg-zinc-900 rounded-[4rem] p-10 md:p-20 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.2)] border border-zinc-100 dark:border-zinc-800">
                         <div className="flex justify-between items-start mb-20">
                            <div><div className="text-6xl md:text-8xl font-black italic tracking-tighter mb-2 tabular-nums">{activeProduct.specs[0].value}<span className="text-brand-500 text-4xl">{activeProduct.specs[0].unit}</span></div><div className="text-xs font-black uppercase tracking-[0.4em] opacity-40 italic">{activeProduct.specs[0].name}</div></div>
                            <div className="bg-brand-500 text-white px-8 py-3 rounded-full text-xs font-black uppercase tracking-widest italic">{t.specs.grade}</div>
                         </div>
                         <SpecsChart data={activeProduct.specs} isDark={isDark} />
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                         <div className="bg-zinc-950 text-white p-12 md:p-16 rounded-[4rem] border border-white/5 hover:border-brand-500/30 transition-all duration-700">
                            <Zap className="mb-10 text-brand-500 group-hover:scale-125 transition-transform" size={48} />
                            <h4 className="text-4xl font-black uppercase mb-6 italic tracking-tighter">{t.specs.efficiencyTitle}</h4>
                            <p className="text-xl opacity-60 font-light leading-relaxed">{t.specs.efficiencyDesc}</p>
                         </div>
                         <div className="bg-white dark:bg-zinc-900 p-12 md:p-16 rounded-[4rem] border border-zinc-100 dark:border-zinc-800 hover:border-brand-500/30 transition-all duration-700">
                            <Sprout className="mb-10 text-brand-500" size={48} />
                            <h4 className="text-4xl font-black uppercase mb-6 italic tracking-tighter">{t.specs.sustainableTitle}</h4>
                            <p className="text-xl opacity-60 font-light leading-relaxed">{t.specs.sustainableDesc}</p>
                         </div>
                      </div>
                   </div>
                </div>
             </div>
          </section>
        </>
      )}

      <footer id="contact" className="bg-zinc-950 text-white relative pt-40 pb-16 px-6 md:px-12 mt-24 rounded-t-[5rem] overflow-hidden group">
         <div className="max-w-[95rem] mx-auto mb-32 border-b border-zinc-800 pb-24 flex flex-col lg:flex-row justify-between items-start lg:items-end gap-20">
            <div>
               <h2 className="text-[12vw] md:text-[10vw] font-black leading-[0.8] tracking-tighter text-white uppercase italic">
                  {t.footer.ctaPrefix} <br/><span className="text-zinc-700 not-italic">{t.footer.ctaHighlight}</span>
               </h2>
            </div>
            <div className="flex flex-col items-start lg:items-end gap-12 w-full lg:w-auto">
                <div className="flex flex-wrap gap-6">
                   {[{ city: 'Kendari', time: worldTimes.kendari, code: 'ID' }, { city: 'London', time: worldTimes.london, code: 'GB' }, { city: 'Shanghai', time: worldTimes.china, code: 'CN' }].map((clock, idx) => (
                     <div key={idx} className="flex items-center gap-6 px-8 py-5 rounded-[2rem] border border-white/10 bg-white/5 backdrop-blur-xl">
                        <div className="flex flex-col"><span className="text-[10px] font-mono text-zinc-500 uppercase tracking-widest mb-2">{clock.city}</span><span className="font-fun text-3xl font-black text-brand-500 tabular-nums leading-none tracking-tighter italic">{clock.time}</span></div>
                        <div className="text-2xl opacity-40 grayscale">{clock.code === 'ID' ? '🇮🇩' : clock.code === 'GB' ? '🇬🇧' : '🇨🇳'}</div>
                     </div>
                   ))}
                </div>
                <button onClick={() => setIsClientModalOpen(true)} className="w-full md:w-auto px-16 py-8 bg-brand-500 hover:bg-brand-400 text-zinc-950 rounded-full text-2xl font-black uppercase italic tracking-tighter transition-all transform hover:scale-105 flex items-center justify-center gap-6 shadow-[0_0_60px_-10px_rgba(16,185,129,0.4)]">
                   {t.footer.startSourcing} <ArrowUpRight size={32} />
                </button>
            </div>
         </div>

         <div className="max-w-[95rem] mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-20 mb-40">
             <div><span className="block text-[10px] font-mono text-zinc-600 mb-12 uppercase tracking-[0.5em]">/// {t.footer.exploreLabel}</span><ul className="space-y-6 text-2xl md:text-3xl font-black uppercase italic tracking-tighter">
                <li><button onClick={() => setView('home')} className="hover:text-brand-500 transition-all duration-500 hover:pl-4">{t.nav.home}</button></li>
                <li><button onClick={() => setView('about')} className="hover:text-brand-500 transition-all duration-500 hover:pl-4">{t.nav.about}</button></li>
                <li><button onClick={() => setView('why-us')} className="hover:text-brand-500 transition-all duration-500 hover:pl-4">{t.nav.whyChooseUs}</button></li>
             </ul></div>
             <div><span className="block text-[10px] font-mono text-zinc-600 mb-12 uppercase tracking-[0.5em]">/// {t.footer.connectLabel}</span><ul className="space-y-6 text-2xl md:text-3xl font-black uppercase italic tracking-tighter">
                <li><a href="mailto:hello@agrovibe.tech" className="hover:text-brand-500 transition-all duration-500 hover:pl-4">Email</a></li>
                <li><a href="#" className="hover:text-brand-500 transition-all duration-500 hover:pl-4">LinkedIn</a></li>
                <li><a href="#" className="hover:text-brand-500 transition-all duration-500 hover:pl-4">Instagram</a></li>
             </ul></div>
             <div className="lg:col-span-2"><span className="block text-[10px] font-mono text-zinc-600 mb-12 uppercase tracking-[0.5em]">/// {t.footer.officeLabel}</span><address className="not-italic text-2xl md:text-3xl text-zinc-400 font-light leading-snug mb-12 whitespace-pre-line tracking-tight">{t.footer.address}</address><a href="mailto:hello@agrovibe.tech" className="text-3xl md:text-5xl font-black hover:text-brand-500 transition-colors border-b-4 border-zinc-800 hover:border-brand-500 pb-4 inline-block italic tracking-tighter uppercase">hello@agrovibe.tech</a></div>
         </div>

         <div className="max-w-[95rem] mx-auto border-t border-zinc-800 pt-12 flex flex-col md:flex-row justify-between items-center gap-10 text-[10px] md:text-xs text-zinc-600 font-mono font-bold uppercase tracking-[0.3em]">
             <div className="flex gap-10"><a href="#" className="hover:text-white">{t.footer.privacy}</a><a href="#" className="hover:text-white">{t.footer.terms}</a></div>
             <div className="flex items-center gap-10"><div className="flex items-center gap-3 px-5 py-2 rounded-full bg-zinc-900 border border-zinc-800"><div className="w-2 h-2 rounded-full bg-brand-500 animate-pulse"></div><span className="text-zinc-400">{t.footer.systemStatus}</span></div><span>&copy; 2026 AgroVibe. {t.footer.rightsReserved}</span></div>
         </div>
         <div className="mt-40 select-none pointer-events-none text-center"><h1 className="text-[22vw] font-black leading-none text-zinc-900 group-hover:text-zinc-800 transition-colors duration-1000 tracking-tighter uppercase italic">AGROVIBE</h1></div>
      </footer>

      {isLangMenuOpen && !isNavOpen && (
        <div className="fixed inset-0 z-50 flex items-end justify-center p-4 md:hidden">
           <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setIsLangMenuOpen(false)}></div>
           <div className="relative w-full max-w-sm bg-white dark:bg-zinc-900 rounded-[3rem] p-10 shadow-2xl animate-fade-up max-h-[70vh] flex flex-col overflow-hidden border border-zinc-200 dark:border-zinc-800">
              <div className="flex justify-between items-center mb-10 shrink-0"><h3 className="text-xl font-black uppercase italic tracking-tighter">{t.nav.selectLanguage}</h3><button onClick={() => setIsLangMenuOpen(false)} className="p-3 bg-zinc-100 dark:bg-zinc-800 rounded-full"><X size={20}/></button></div>
              <div className="flex flex-col gap-3 overflow-y-auto">
                 {(Object.keys(LANG_CONFIG) as Language[]).map((langKey) => (
                   <button key={langKey} onClick={() => { setLang(langKey); setIsLangMenuOpen(false); }} className={`flex items-center justify-between px-6 py-6 rounded-3xl border-2 transition-all shrink-0 ${lang === langKey ? 'bg-brand-50 dark:bg-brand-900/20 border-brand-500' : 'border-zinc-100 dark:border-zinc-800'}`}>
                     <div className="flex items-center gap-6"><span className="text-4xl">{LANG_CONFIG[langKey].flag}</span><div className="flex flex-col items-start"><span className="font-black text-lg uppercase italic tracking-tighter leading-none mb-1">{langKey}</span><span className="text-[10px] opacity-40 uppercase tracking-widest font-mono">Select Region</span></div></div>
                     {lang === langKey && <div className="w-8 h-8 bg-brand-500 rounded-full flex items-center justify-center text-white"><Check size={18} /></div>}
                   </button>
                 ))}
              </div>
           </div>
        </div>
      )}

      {cookieConsent === null && <CookieConsent t={t.cookieConsent} onAccept={() => setCookieConsent('accepted')} onDecline={() => setCookieConsent('declined')} />}

      {isClientModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-xl" onClick={() => setIsClientModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-zinc-900 w-full max-w-2xl rounded-[4rem] p-10 md:p-20 shadow-2xl border border-zinc-200 dark:border-zinc-800 animate-fade-up max-h-[95vh] overflow-y-auto">
            <button onClick={() => setIsClientModalOpen(false)} className="absolute top-10 right-10 p-3 rounded-full hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"><X size={24} /></button>
            <h3 className="text-4xl md:text-6xl font-black uppercase italic tracking-tighter mb-6">{t.clientForm.title}</h3>
            <p className="text-xl text-zinc-500 dark:text-zinc-400 mb-12 font-light leading-snug">{t.clientForm.subtitle}</p>
            <form className="space-y-8" onSubmit={(e) => { e.preventDefault(); alert("Inquiry sent!"); setIsClientModalOpen(false); }}>
               <div><label className="block text-[10px] font-black uppercase tracking-[0.4em] mb-4 text-zinc-400 italic">{t.clientForm.name}</label><input required type="text" className="w-full bg-zinc-50 dark:bg-zinc-800 border-2 border-zinc-100 dark:border-zinc-700 rounded-2xl px-6 py-5 focus:outline-none focus:border-brand-500 font-bold transition-all" /></div>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                 <div><label className="block text-[10px] font-black uppercase tracking-[0.4em] mb-4 text-zinc-400 italic">{t.clientForm.origin}</label><input required type="text" className="w-full bg-zinc-50 dark:bg-zinc-800 border-2 border-zinc-100 dark:border-zinc-700 rounded-2xl px-6 py-5 focus:outline-none focus:border-brand-500 font-bold transition-all" /></div>
                 <div><label className="block text-[10px] font-black uppercase tracking-[0.4em] mb-4 text-zinc-400 italic">{t.clientForm.whatsapp}</label><input required type="tel" className="w-full bg-zinc-50 dark:bg-zinc-800 border-2 border-zinc-100 dark:border-zinc-700 rounded-2xl px-6 py-5 focus:outline-none focus:border-brand-500 font-bold transition-all" /></div>
               </div>
               <div><label className="block text-[10px] font-black uppercase tracking-[0.4em] mb-4 text-zinc-400 italic">{t.clientForm.product}</label><select className="w-full bg-zinc-50 dark:bg-zinc-800 border-2 border-zinc-100 dark:border-zinc-700 rounded-2xl px-6 py-5 focus:outline-none focus:border-brand-500 font-bold appearance-none transition-all uppercase tracking-widest text-xs">
                  {products.map(p => <option key={p.id} value={p.title}>{p.title}</option>)}
               </select></div>
               <button type="submit" className="w-full bg-brand-500 hover:bg-brand-600 text-white font-black uppercase italic tracking-tighter text-2xl py-6 rounded-2xl transition-all shadow-xl hover:shadow-brand-500/30 transform hover:scale-[1.02] active:scale-95">{t.clientForm.submit}</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
